using System.Reflection;
using System.Text;
using UltrasoundHost.Contracts;

namespace UltrasoundHost.Tests;

/// <summary>
/// R10: the contract public API only grows. A snapshot of every exported type and member is kept in
/// <c>ContractsApiSnapshot.txt</c>; changing the API without updating the snapshot (and the contract
/// version) fails this test. 07 wanted PublicApiAnalyzers here, but the analyzers available for the
/// bundled Roslyn 4.11 cannot generate their file offline, so the same rule is enforced as a test
/// snapshot (B-level). The snapshot is regenerated by copying the actual file written on failure.
/// </summary>
public class ApiSnapshotTests
{
    private const string SnapshotFileName = "ContractsApiSnapshot.txt";

    [Fact]
    public void R10_contracts_public_api_matches_the_snapshot_and_the_contract_version()
    {
        string snapshotPath = Path.Combine(SolutionRoot(), "tests", "UltrasoundHost.Tests", SnapshotFileName);
        Assert.True(File.Exists(snapshotPath), "missing " + SnapshotFileName);

        string[] snapshotLines = File.ReadAllLines(snapshotPath);
        Assert.True(snapshotLines.Length >= 2, "the API snapshot must start with a version line");
        Assert.Equal("# version " + ContractsInfo.Current, snapshotLines[0]);

        string[] expected = snapshotLines.Skip(1).ToArray();
        string[] actual = GenerateApiLines();
        if (expected.SequenceEqual(actual))
        {
            return;
        }

        string actualPath = Path.Combine(SolutionRoot(), "TestResults", "ContractsApiSnapshot.actual.txt");
        Directory.CreateDirectory(Path.GetDirectoryName(actualPath)!);
        File.WriteAllLines(actualPath, new[] { "# version " + ContractsInfo.Current }.Concat(actual));
        Assert.Fail(
            "the contracts public API differs from " + SnapshotFileName + ". If the change only adds members, "
            + "copy TestResults/ContractsApiSnapshot.actual.txt over the snapshot and keep ContractsInfo.Current in sync (R10).");
    }

    private static string[] GenerateApiLines()
    {
        Assembly assembly = typeof(PluginManifest).Assembly;
        var lines = new List<string>();
        foreach (Type type in assembly.GetExportedTypes().OrderBy(candidate => candidate.FullName, StringComparer.Ordinal))
        {
            lines.Add("T:" + FormatType(type));
            foreach (MemberInfo member in type.GetMembers(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly))
            {
                switch (member)
                {
                    case ConstructorInfo constructor:
                        lines.Add("C:" + FormatType(type) + "(" + FormatParameters(constructor.GetParameters()) + ")");
                        break;

                    case MethodInfo method when !method.IsSpecialName:
                        lines.Add("M:" + FormatType(type) + "." + method.Name
                            + "(" + FormatParameters(method.GetParameters()) + ") -> " + FormatType(method.ReturnType));
                        break;

                    case PropertyInfo property:
                        string accessors = (property.GetMethod is not null ? "get" : string.Empty)
                            + (property.SetMethod is not null ? (property.GetMethod is not null ? ",set" : "set") : string.Empty);
                        lines.Add("P:" + FormatType(type) + "." + property.Name + " -> " + FormatType(property.PropertyType) + " [" + accessors + "]");
                        break;

                    case FieldInfo field:
                        lines.Add("F:" + FormatType(type) + "." + field.Name + " -> " + FormatType(field.FieldType));
                        break;

                    case EventInfo @event:
                        lines.Add("E:" + FormatType(type) + "." + @event.Name + " -> " + FormatType(@event.EventHandlerType!));
                        break;
                }
            }
        }

        lines.Sort(StringComparer.Ordinal);
        return lines.ToArray();
    }

    private static string FormatParameters(ParameterInfo[] parameters) =>
        string.Join(", ", parameters.Select(parameter => FormatType(parameter.ParameterType)));

    private static string FormatType(Type type)
    {
        if (type.IsGenericType)
        {
            string name = type.GetGenericTypeDefinition().FullName ?? type.Name;
            int tick = name.IndexOf('`');
            if (tick >= 0)
            {
                name = name[..tick];
            }

            return name + "<" + string.Join(", ", type.GetGenericArguments().Select(FormatType)) + ">";
        }

        return type.FullName ?? type.Name;
    }

    private static string SolutionRoot()
    {
        string? directory = AppContext.BaseDirectory;
        while (directory is not null)
        {
            if (File.Exists(Path.Combine(directory, "Directory.Build.props")))
            {
                return directory;
            }

            directory = Path.GetDirectoryName(directory);
        }

        throw new InvalidOperationException("could not find the solution root from " + AppContext.BaseDirectory);
    }
}
